&lt;p&gt;Req. ID: 426133&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;MongoDB’s base salary range for this role is posted below. Compensation at the time of offer is unique to each candidate and based on a variety of factors such as skill set, experience, qualifications, and work location. Salary is one part of MongoDB’s total compensation and benefits package. Other benefits for eligible employees may include: equity, participation in the employee stock purchase program, flexible paid time off, 20 weeks fully-paid gender-neutral parental leave, fertility and adoption assistance, 401(k) plan, mental health counseling, access to transgender-inclusive health insurance coverage, and health benefits offerings. Please note, the base salary range listed below and the benefits in this paragraph are only applicable to U.S.-based candidates.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;MongoDB’s base salary range for this role in the U.S. is:&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$60,008&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$60,008 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;","departments":[{"id":69389,"name":"Commercial Growth","child_ids":[],"parent_id":336792}],"offices":[{"id":3964,"name":"Austin","location":"Austin, TX, United States","child_ids":[],"parent_id":23657}],"ai_disclaimer":null,"include_ai_disclaimer":false,"ai_opt_out_request_url":null},{"absolute_url":"https://www.mongodb.com/careers/job/?gh_jid=8173777","data_compliance":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":true}],"internal_job_id":3537539,"location":{"name":"Gurugram"},"metadata":[{"id":22194060,"name":"Position ID","value":"10001418","value_type":"short_text"},{"id":24918,"na